1. @page "/board"
2. @using sv_304f70a8d306440ab67bf17273ce5b74.Components.Pages.BoardComponents
3. @rendermode InteractiveServer
4. @inject ITaskService TaskService
5. 
6. <PageTitle>Kanban Board</PageTitle>
7. 
8. <h3 class="mb-3">Project Board</h3>
9. 
10. @if (loading)
11. {
12.     <div class="d-flex justify-content-center my-5">
13.         <div class="spinner-border" role="status">
14.             <span class="visually-hidden">Loading...</span>
15.         </div>
16.     </div>
17. }
18. else if (errorMessage is not null)
19. {
20.     <div class="alert alert-danger">@errorMessage</div>
21. }
22. else
23. {
24.     <BoardStats Total="allTasks.Count"
25.                 TodoCount="TodoTasks.Count"
26.                 InProgressCount="InProgressTasks.Count"
27.                 DoneCount="DoneTasks.Count"
28.                 OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />
29. 
30.     <TaskSearch SearchText="@searchText" SearchTextChanged="text => searchText = text" />
31. 
32.     <div class="row g-3">
33.         <KanbanColumn Title="To Do"
34.                       Tasks="TodoTasks"
35.                       ShowMoveLeft="false"
36.                       ShowMoveRight="true"
37.                       OnMoveRight="@(id => MoveTask(id, StatusInProgress))"
38.                       OnAddTask="@(model => AddTask(model, StatusTodo))" />
39. 
40.         <KanbanColumn Title="In Progress"
41.                       Tasks="InProgressTasks"
42.                       ShowMoveLeft="true"
43.                       ShowMoveRight="true"
44.                       OnMoveLeft="@(id => MoveTask(id, StatusTodo))"
45.                       OnMoveRight="@(id => MoveTask(id, StatusDone))"
46.                       OnAddTask="@(model => AddTask(model, StatusInProgress))" />
47. 
48.         <KanbanColumn Title="Done"
49.                       Tasks="DoneTasks"
50.                       ShowMoveLeft="true"
51.                       ShowMoveRight="false"
52.                       OnMoveLeft="@(id => MoveTask(id, StatusInProgress))"
53.                       OnAddTask="@(model => AddTask(model, StatusDone))" />
54.     </div>
55. }
56. 
57. @code {
58.     private const string StatusTodo = "To Do";
59.     private const string StatusInProgress = "In Progress";
60.     private const string StatusDone = "Done";
61. 
62.     private List<TaskItem> allTasks = new();
63.     private string searchText = "";
64.     private bool loading = true;
65.     private string? errorMessage;
66. 
67.     private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(searchText)
68.         ? allTasks
69.         : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
70. 
71.     private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == StatusTodo).ToList();
72.     private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == StatusInProgress).ToList();
73.     private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == StatusDone).ToList();
74. 
75.     protected override async Task OnInitializedAsync()
76.     {
77.         try
78.         {
79.             allTasks = await TaskService.GetAllTasksAsync();
80.         }
81.         catch (Exception ex)
82.         {
83.             errorMessage = $"Failed to load tasks: {ex.Message}";
84.         }
85.         finally
86.         {
87.             loading = false;
88.         }
89.     }
90. 
91.     private async Task MoveTask(int taskId, string newStatus)
92.     {
93.         try
94.         {
95.             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
96.             var task = allTasks.First(t => t.Id == taskId);
97.             allTasks = allTasks.Select(t => t.Id == taskId ? task with { Status = newStatus } : t).ToList();
98.         }
99.         catch (Exception ex)
100.         {
101.             errorMessage = $"Failed to move task: {ex.Message}";
102.         }
103.     }
104. 
105.     private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
106.     {
107.         try
108.         {
109.             var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
110.             // CreateTaskAsync returns with default status; override with column status
111.             allTasks.Add(newTask with { Status = status });
112.         }
113.         catch (Exception ex)
114.         {
115.             errorMessage = $"Failed to create task: {ex.Message}";
116.         }
117.     }
118. }
119.

