 @page "/board"
 @using sv_304f70a8d306440ab67bf17273ce5b74.Components.Pages.BoardComponents
 @rendermode InteractiveServer
 @inject ITaskService TaskService

 <PageTitle>Kanban Board</PageTitle>

 <h3 class="mb-3">Project Board</h3>

 @if (loading)
 {
     <div class="d-flex justify-content-center my-5">
         <div class="spinner-border" role="status">
             <span class="visually-hidden">Loading...</span>
         </div>
     </div>
 }
 else if (errorMessage is not null)
 {
     <div class="alert alert-danger">@errorMessage</div>
 }
 else
 {
     <BoardStats Total="allTasks.Count"
                 TodoCount="TodoTasks.Count"
                 InProgressCount="InProgressTasks.Count"
                 DoneCount="DoneTasks.Count"
                 OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

     <TaskSearch SearchText="@searchText" SearchTextChanged="text => searchText = text" />

     <div class="row g-3">
         <KanbanColumn Title="To Do"
                       Tasks="TodoTasks"
                       ShowMoveLeft="false"
                       ShowMoveRight="true"
                       OnMoveRight="@(id => MoveTask(id, StatusInProgress))"
                       OnAddTask="@(model => AddTask(model, StatusTodo))" />

         <KanbanColumn Title="In Progress"
                       Tasks="InProgressTasks"
                       ShowMoveLeft="true"
                       ShowMoveRight="true"
                       OnMoveLeft="@(id => MoveTask(id, StatusTodo))"
                       OnMoveRight="@(id => MoveTask(id, StatusDone))"
                       OnAddTask="@(model => AddTask(model, StatusInProgress))" />

         <KanbanColumn Title="Done"
                       Tasks="DoneTasks"
                       ShowMoveLeft="true"
                       ShowMoveRight="false"
                       OnMoveLeft="@(id => MoveTask(id, StatusInProgress))"
                       OnAddTask="@(model => AddTask(model, StatusDone))" />
     </div>
 }

 @code {
     private const string StatusTodo = "To Do";
